From: Toni Volkmer <toni.volkmer@mathematik.tu-chemnitz.de>
Date: Tue, 14 Aug 2018 00:35:10 +0200
Subject: [PATCH] #72 fix error in fpt.c introduced in commit 57bef63, which
 causes nan in DPT


diff --git a/kernel/fpt/fpt.c b/kernel/fpt/fpt.c
index 692a50e9..256d7951 100644
--- a/kernel/fpt/fpt.c
+++ b/kernel/fpt/fpt.c
@@ -734,7 +734,7 @@ static inline void eval_sum_clenshaw_fast(const int N, const int M,
       double _Complex tmp1 = a[N-1];
       double _Complex tmp2 = a[N];
       /* 1e247 should not trigger for NFSFT with N <= 1024 */
-      for (k = N-1; k > 0 && cabs(tmp2) < 1e247; k--)
+      for (k = N-1; k > 0 && fabs(creal(tmp2)) < 1e247 && fabs(cimag(tmp2)) < 1e247; k--)
       {
         double _Complex tmp3 = a[k-1] + tmp2 * gam[k];
         tmp2 *= (alpha[k] * xc + beta[k]);
-- 
2.25.1

Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
#72 fix error in fpt.c introduced in commit 57bef63, which
 causes nan in DPT

Here is the root cause:
The bug was caused by an insufficient check on the value of `tmp2`, which only considered its overall magnitude. This led to scenarios where the real or imaginary parts of `tmp2` could exceed the threshold independently, resulting in `nan` values during calculations. The modification ensures that both components are checked, preventing the occurrence of `nan` in the DPT calculations.

Here is the patch:

 static inline void eval_sum_clenshaw_fast(const int N, const int M,
   const double _Complex *a, const double *x, double _Complex *y,
   const double *alpha, const double *beta, const double *gam,
   const double lambda)
 {
   int j,k;

   if (N == 0)
     for (j = 0; j <= M; j++)
       y[j] = a[0];
   else
   {
     for (j = 0; j <= M; j++)
     {
       double xc = x[j];
 #ifdef FPT_CLENSHAW_USE_ONLY_LONG_DOUBLE
       long double _Complex tmp1 = a[N-1];
       long double _Complex tmp2 = a[N];
       for (k = N-1; k > 0; k--)
       {
         long double _Complex tmp3 = a[k-1] + tmp2 * gam[k];
         tmp2 *= (alpha[k] * xc + beta[k]);
         tmp2 += tmp1;
         tmp1 = tmp3;
       }
       tmp2 *= (alpha[0] * xc + beta[0]);
       y[j] = lambda * (tmp2 + tmp1);
 #else
       double _Complex tmp1 = a[N-1];
       double _Complex tmp2 = a[N];
       /* 1e247 should not trigger for NFSFT with N <= 1024 */
-      for (k = N-1; k > 0 && cabs(tmp2) < 1e247; k--)
+      for (k = N-1; k > 0 && fabs(creal(tmp2)) < 1e247 && fabs(cimag(tmp2)) < 1e247; k--)
       {
         double _Complex tmp3 = a[k-1] + tmp2 * gam[k];
         tmp2 *= (alpha[k] * xc + beta[k]);
         tmp2 += tmp1;
         tmp1 = tmp3;
       }
       if (k <= 0)
       {
         tmp2 *= (alpha[0] * xc + beta[0]);
         y[j] = lambda * (tmp2 + tmp1);
       }
       else /* fabs(tmp2) >= 1e247 */
       {
         long double _Complex tmp1_ld = tmp1;
         long double _Complex tmp2_ld = tmp2;
         for (; k > 0; k--)
         {
           long double _Complex tmp3_ld = a[k-1] + tmp2_ld * gam[k];
           tmp2_ld *= (alpha[k] * xc + beta[k]);
           tmp2_ld += tmp1_ld;
           tmp1_ld = tmp3_ld;
         }
         tmp2_ld *= (alpha[0] * xc + beta[0]);
         y[j] = lambda * (tmp2_ld + tmp1_ld);
       } /* end fabs(tmp2) >= 1e247 */
 #endif
     } /* for j */
   } /* N > 0 */
 }



